  'hint.defibrillator': ['对准 {range} 格内倒地的其他玩家，长按使用 {duration}s；无需篝火，用后消失。', 'Aim at another downed player within {range} tiles and hold use for {duration}s. No fire needed; single use.'],
  'hint.reviveTarget': ['救援 {name} · {range} 格内长按 {duration}s，回满体温与饥饿；松手取消。', 'Revive {name} · Hold {duration}s within {range} tiles to restore temperature and hunger. Release to cancel.'],
  'admin.title': ['管理员控制台', 'Administrator console'],
