  'item.healing': ['{name} · 长按 {duration} 秒 · 体温恢复至 {temperature}°C、饥饿至少 {hunger} · 无需篝火', '{name} · Hold {duration} s · Restore to {temperature}°C and at least {hunger} hunger · No fire needed'],
